uniform float Gain = 0.5;

/// @slider 0.0 4.0
uniform float Boost = 2.0;

uniform float2 Offset = float2(0.25, 0.75);
uniform float3 Colour = float3(1.0, 0.5, 0.25);
uniform float4 Full = float4(0.1, 0.2, 0.3, 0.4);

/// @sort 6
/// @sampler Color
uniform Texture2D Source;

/// @sort 70
uniform float Late = 1.0;

export void M_DUniformWidths(inout material m)
{
    float2 UV = UE.TextureCoordinate(CoordinateIndex = 0) + Offset;

    m.EmissiveColor = Colour * Gain * Boost + Source.Sample(UV).xyz * Full.xyz;
    m.Opacity = Full.w * Late;
}
